"""
    Property: AttributeDefinition.AttributeType
    """
def attribute_type_validator(x: Any) -> object {
    valid_types = ["S", "N", "B"];
    if (x not in valid_types) {
        raise ValueError(("AttributeType must be one of: %s" % ", ".join(valid_types)));
    }
    return x;
}

